mapper.select:
select  from mall_banner

    and position = #{position}
    and status = #{status}

order by position asc, sort asc, id desc

mapper.update:
update mall_banner
title = #{title}, image = #{image}, position = #{position}, link_type = #{linkType}, link_value = #{linkValue}, sort = #{sort}, status = #{status}, start_time = #{startTime}, end_time = #{endTime}, update_time = now()
where id = #{id}
